import{_ as e,o as r,c as s,a3 as p}from"./chunks/framework.BwzYn71E.js";const b=JSON.parse('{"title":"物流原理与一些名词","description":"","frontmatter":{"translationSource":{"title":"物流原理与一些名词","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Ul3PjfHfEH7t9ofd3SfA1L","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/logistics-principles-and-frontier-research"}]]},"headers":[],"relativePath":"zh/logistics-principles-and-frontier-research.md","filePath":"zh/page-Ul3PjfHfEH7t9ofd3SfA1L.md"}'),o={name:"zh/logistics-principles-and-frontier-research.md"};function t(i,a,n,l,d,c){return r(),s("div",null,[...a[0]||(a[0]=[p('<div class="logistics-content"><h1 id="物流原理与一些名词" tabindex="-1">物流原理与一些名词 <a class="header-anchor" href="#物流原理与一些名词" aria-label="Permalink to &quot;物流原理与一些名词&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>本页内容更新：</span><a href="/endfield-skydoc/zh/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。" aria-label="本页内容更新：2026-11-23. 网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。"><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone">（北京时间）</span></p><blockquote><p>源页面 ID：<code>Ul3PjfHfEH7t9ofd3SfA1L</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Ul3PjfHfEH7t9ofd3SfA1L" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>本页面目前主要由 jnk 维护中</p><p><span id="source-block-5L4w3zMYiVCfmdi6ASRqkO"></span></p><h2 id="物流bug分析" tabindex="-1">物流bug分析 <a class="header-anchor" href="#物流bug分析" aria-label="Permalink to &quot;物流bug分析&quot;">​</a></h2><p><a href="/endfield-skydoc/zh/input-output-merge-priority-theory">优先输入/输出/汇入理论简要说明</a></p><p><a href="/endfield-skydoc/zh/introduction-to-analyzing-endfield-logistics-bugs">终末地物流bug分析导论</a></p><p><span id="source-block-Ik2ViXezbe9d6VFUOZIUc6"></span></p><h2 id="一些各式各样的特殊结构定义" tabindex="-1">一些各式各样的特殊结构定义 <a class="header-anchor" href="#一些各式各样的特殊结构定义" aria-label="Permalink to &quot;一些各式各样的特殊结构定义&quot;">​</a></h2><p><span id="source-block-f5f4WE5OyQHLDbhWbKgmAv"></span></p><h3 id="滤波器" tabindex="-1">滤波器 <a class="header-anchor" href="#滤波器" aria-label="Permalink to &quot;滤波器&quot;">​</a></h3><p>狭义滤波器：将输入的不均匀序列转化为更加均匀的序列，例如将10110 10011转化为10110 10110，有时也被叫做<strong>稳流器</strong></p><p>在满带输入的情况下等同于某种较为均匀的限流器</p><p>广义滤波器：低通：将超过设定流量范围的序列流放到其他地方，通常为插入低于设定流量范围的序列中或者流出结构。高通：与低通相反。</p><p><span id="source-block-6wMXamjZ5Q8JK8QhmLPm7f"></span></p><h3 id="切换检测器" tabindex="-1">切换检测器 <a class="header-anchor" href="#切换检测器" aria-label="Permalink to &quot;切换检测器&quot;">​</a></h3><p>在输入物品种类切换时，向上游传递一定时间阻塞效果的容器。通常容量较大。</p><p><span id="source-block-bxoKy84qBhJdi0XP4neKaG"></span></p><h4 id="管道" tabindex="-1">管道 <a class="header-anchor" href="#管道" aria-label="Permalink to &quot;管道&quot;">​</a></h4><p>管道在输入物品种类切换时，会因为同时只有一种液体的要求，使得后一种液体需要等前一种液体最后一滴流出管道，此时切换后的阻塞效果时间与管道长度正相关。</p><p><span id="source-block-0XZQW4y0Ab7dxcTaBH1LGr"></span></p><h4 id="单物品容器" tabindex="-1">单物品容器 <a class="header-anchor" href="#单物品容器" aria-label="Permalink to &quot;单物品容器&quot;">​</a></h4><p>只能容纳单种物品的容器，在其内部物品完全输出后，才能接受一种新的物品，可以视为切换后的阻塞效果时间与内部物品数正相关、与输出平均速度负相关。</p><p>此外有一种特殊的应用方法，在要求只有某种液体完全输入该容器后过一段时间后才能开始流出时，其阻塞时长与系统该物品总数成正比。此时下游从阻塞变为流通的信号需要等待固定时间才能向上游传递。</p><p><span id="source-block-9j2XLqzFcpwJ8W5QQIYeRK"></span></p><h3 id="整流器" tabindex="-1">整流器 <a class="header-anchor" href="#整流器" aria-label="Permalink to &quot;整流器&quot;">​</a></h3><p>狭义整流器：将输入的序列转化为连续1/0序列，例如将10110 10011转化为11100 11100</p><p>在满带/过大流量输入下对上游传递连续1/0序列的阻塞信号</p><p>广义整流器：将输入流转化为特定结构流量，典型的是转化为连续流和0流量，还有转化为特定序列，例如完美均匀序列</p><p><span id="source-block-qRQBmPKZ0UOWx8eTbhcphN"></span></p><h4 id="连续物品补式整流" tabindex="-1"><strong>连续物品补式整流</strong> <a class="header-anchor" href="#连续物品补式整流" aria-label="Permalink to &quot;**连续物品补式整流**&quot;">​</a></h4><p>将连续的辅助物品作为基本控制结构的控制输入，使得同时输入控制结构的受控物品必须延后到可以通行时才能通行，而通行时又是连续的，即达成一段连续流量。这一类整流有时因为下线降速而损坏（降速使得连续物品变为不连续）。该类整流又分为两类：</p><p><span id="source-block-jiYkj5PpL5l2w3MFGeN0Zs"></span></p><h4 id="沙漏式整流" tabindex="-1"><strong>沙漏式整流</strong> <a class="header-anchor" href="#沙漏式整流" aria-label="Permalink to &quot;**沙漏式整流**&quot;">​</a></h4><p>基于切换检测器\\单物品容器构建</p><p><span id="source-block-dey4t7kblTAWoIHHqzUYE7"></span></p><h3 id="溢流器" tabindex="-1">溢流器 <a class="header-anchor" href="#溢流器" aria-label="Permalink to &quot;溢流器&quot;">​</a></h3><p>狭义溢流器：输入在两个输出口之间有严格优先级关系，即在A没有满到无法输出前B都不会有流量。</p><p>广义溢流器：输入在两个输出口之间有不严格优先级关系，即在空载情况下，输出到高优先A方向的流量大于A满载时最大通行流量。</p><p><span id="source-block-n9B7tFb0RiVmFdwgWv9DxN"></span></p><h3 id="限流器" tabindex="-1">限流器 <a class="header-anchor" href="#限流器" aria-label="Permalink to &quot;限流器&quot;">​</a></h3><p>单入口单出口的物流结构，限制平均通过流量的上限，不保证输出为特定序列。有时也叫做限速器。</p><p><span id="source-block-feYWNsMRluyjDzYHJU8HVp"></span></p><h3 id="溢流器-优先输出器" tabindex="-1">溢流器/优先输出器 <a class="header-anchor" href="#溢流器-优先输出器" aria-label="Permalink to &quot;溢流器/优先输出器&quot;">​</a></h3><p>单输入双输出的物流结构。</p><p>狭义 溢流器/优先输出器：对于一段时间窗口内的输入，如果高优先输出方向流通，则低优先方向没有流量。符合直觉的输入优先去往高优先方向。对于满带输入的情况，有时也被称为<strong>流量复制器</strong>，对其高优先方向施加阻塞信号，就会在低优先方向输出与阻塞信号时间相当的物品。</p><p>广义 溢流器/优先输出器：假定其各输出方向流通时，输出流量是固定比例的。对于长期平均输入，固定比例分配后，高优先方向消耗速度低于其分配得到的总流量。尽管在高优先方向非流通前，其输出成比例，与优先的名义无关；但是高优先方向积累物品至非流通后，结构效果等效于狭义版本。</p><p><span id="source-block-gk0ftJwaqdj335twrpq0qB"></span></p><h3 id="优先汇流器" tabindex="-1">优先汇流器 <a class="header-anchor" href="#优先汇流器" aria-label="Permalink to &quot;优先汇流器&quot;">​</a></h3><p>狭义优先汇流器：基于优先汇流 的原理制作的 分流器→汇流器;传送带→汇流器 结构，由于总流量小于等于1，当高优先方向输入流量1时，低优先方向就会变成流量0，使得低优先方向&quot;阻断&quot;。</p><p>广义优先汇流器：类似广义优先输出器，在保证输出达到特定大小后可以保证其中一侧输入不阻塞即可。</p><p><span id="source-block-Tr4QvYq1Ruz7WvejwO5RcS"></span></p><h3 id="筛分器-过滤器-分类器-分离器" tabindex="-1">筛分器\\过滤器\\分类器\\分离器 <a class="header-anchor" href="#筛分器-过滤器-分类器-分离器" aria-label="Permalink to &quot;筛分器\\过滤器\\分类器\\分离器&quot;">​</a></h3><p>本段内若有引用均使用分类器的称呼，本质是分流器→只能接受某种流体\\物品的容器，通常容器使用的是过滤准入口。有时有特殊需求（压元件、压地）会使用类似管道\\暗管只能存储一种流体、固气\\液气机激活物口只接受激活物之类的设备代替容器。</p><p><span id="source-block-TwAdfmWti8bBHTAGCmTcqt"></span></p><h3 id="基本控制结构" tabindex="-1">基本控制结构 <a class="header-anchor" href="#基本控制结构" aria-label="Permalink to &quot;基本控制结构&quot;">​</a></h3><p>基本控制结构是两输入两输出的结构，两种输入分别对应一种输出，两种输入有一侧控制端与一侧受控端，控制端流量为1时阻断受控端。基本控制结构假定输出流通。</p><p><span id="source-block-msCpcnAU4hdiRv7T0efvi5"></span></p><h4 id="固固-流流-基本控制结构" tabindex="-1">固固\\流流-基本控制结构 <a class="header-anchor" href="#固固-流流-基本控制结构" aria-label="Permalink to &quot;固固\\流流-基本控制结构&quot;">​</a></h4><p>常用实现是优先汇流器→分类器，确保输入输出都是纯净两种，同时由优先汇流器的特性实现其中一端输入控制另一端输入的效果。最终效果类似优先汇流器，只是输出是多种。</p><p><span id="source-block-WAa6YT2JcwqSHP14sGqTCT"></span></p><h4 id="固液-基本控制结构" tabindex="-1">固液-基本控制结构 <a class="header-anchor" href="#固液-基本控制结构" aria-label="Permalink to &quot;固液-基本控制结构&quot;">​</a></h4><p>常用实现1：断电反应池可以接受固体与液体，通过这种方式可以实现同增同减（同一格），配合取反器即可实现基本控制结构，类似的，使用有液体+固体的配方的设备也可以直接达成同增同减。</p><p><span id="source-block-XKuBsS73GKwpAOmtYCmWDS"></span></p><h3 id="反向基本控制结构-定比例汇流器" tabindex="-1">反向基本控制结构/定比例汇流器 <a class="header-anchor" href="#反向基本控制结构-定比例汇流器" aria-label="Permalink to &quot;反向基本控制结构/定比例汇流器&quot;">​</a></h3><p>反向基本控制结构也是两输入两输出的结构，但是是输出有控制端和受控端。其假定输入阻塞（充足）。与广义汇流器的区别在于，广义汇流器是对相同液体的汇流。反向基本控制结构保证两个输出的比例相同。</p><p><span id="source-block-43mxU8WxSkD6eR8LkKUVn8"></span></p><h3 id="取反器" tabindex="-1">取反器 <a class="header-anchor" href="#取反器" aria-label="Permalink to &quot;取反器&quot;">​</a></h3><p>双输入双输出的物流结构。存在一侧输入输出为控制端，另一侧输入输出为受控端。</p><p>大致结构如下：</p><p>受控输入-低优先汇入&gt;优先汇入器→限速器→优先输出器-低优先输出（溢流）→受控输出；</p><p>优先输出器-高优先输出-受控端→控制结构-受控物料-优先汇入→优先汇入器；</p><p>控制输入→控制结构→控制输出</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d642b938a9367404.q90-d9ae26130ec77849.webp" alt="物流原理与一些名词"></p><p>控制结构每当被控制着输出，受控端就会对应的不输出。就结果上将控制结构的结果反相了，所以叫做取反器，根据控制结构不同有不同的效果。</p><p>一种比较常见的结果如图所示，这个通常被称为 赤铜气液气前馈 ，效果是赤铜气输入不足时，息壤气减少输入。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-84ea65b05b721d23.q90-b587c317b2f3d88e.webp" alt="物流原理与一些名词"></p><p>如果控制结构为反向基本控制结构时，确保控制输出端限速为特定值时，其可以确保控制输出与受控输出总和为定值，在某些情况下可以视作优先级架构。</p><p><span id="source-block-S8PWbXu9lpMq8KlwIZxgRB"></span></p><h3 id="连续空位发生器-连续物品发生器" tabindex="-1">连续空位发生器/连续物品发生器 <a class="header-anchor" href="#连续空位发生器-连续物品发生器" aria-label="Permalink to &quot;连续空位发生器/连续物品发生器&quot;">​</a></h3><p>在收到信号后，输出一连串空位/物品的元件。输入输出数通常不定。</p><p><span id="source-block-rF768UficaFulfX1mHS9yR"></span></p><h4 id="奇偶滞涩式" tabindex="-1">奇偶滞涩式 <a class="header-anchor" href="#奇偶滞涩式" aria-label="Permalink to &quot;奇偶滞涩式&quot;">​</a></h4><p>通过长1格的距离，将辅助物品滞后一格，使其与本应在同一格的目标物品冲突，汇流时，由于之前经过过目标物品（满带目标物品），会先汇流辅助物品方向，使得目标物品被阻塞滞后一格，于是辅助物品前就多空出来一位了，通过堆叠该结构，就可以产生连续的n+1（n为结构个数）个空位。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5b646c09003ea60c.q90-6a93481adb9455c8.webp" alt="物流原理与一些名词"></p><p><span id="source-block-ZZSfbctDNK0aQpPr2myvCj"></span></p><h4 id="切换检测式" tabindex="-1">切换检测式 <a class="header-anchor" href="#切换检测式" aria-label="Permalink to &quot;切换检测式&quot;">​</a></h4><p>单物品容器在切换时，会对上游提供内涵物品N的阻塞信号，通过流量复制器（优先输出器），可以将这连续的阻塞信号转化为连续物品流N，由于汇流也会导致1的阻塞信号，最终输出为N+1。</p><p>为了消除1的影响，需在辅助物品输入时使用基本控制结构从中扣除1的物品，使输出回归N。</p><p>由于单物品容器在这样切换后，内涵物品数量会归零，输出的物品流N需要使用后归还到单物品容器，使用基本控制结构将连续辅助物品转换为目标物品带的连续空位后，将辅助物品归还单物品容器。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8be9051d5255768a.q90-690009b5c61cd79f.webp" alt="物流原理与一些名词"></p><div class="logistics-image-caption" data-source-block="HNJmbzpnnP9zAmoNtsjM64"><p>此处的每条边都是单条传送带</p></div><p><span id="source-block-wO7xPIiHDJwfeAtqFW4VJE"></span></p><h2 id="均匀性与极差" tabindex="-1">均匀性与极差 <a class="header-anchor" href="#均匀性与极差" aria-label="Permalink to &quot;均匀性与极差&quot;">​</a></h2><p><span id="source-block-BKd0bfBqMQYjGOon5TjRNh"></span></p><h3 id="均匀二进制分流器" tabindex="-1">均匀二进制分流器 <a class="header-anchor" href="#均匀二进制分流器" aria-label="Permalink to &quot;均匀二进制分流器&quot;">​</a></h3><details><summary><span class="mark-grey">Bresenham算法讲述</span></summary><p>理想情况下，我们希望输出总物品量与时间成正比，n=Kt，但是实际上我们只能取n, t为整数，我们维护一个输出偏差值a，每单位时间内，n会增加K，我们使得a也增加K，如果a+K之后误差大于1，就输出一个，使得误差降低1变回&lt;1的状态，从而保持误差小于1</p></details><p><span id="source-block-NOQ4vy8rsvDM9q7qet2tpl"></span></p><h4 id="edwardkerman式" tabindex="-1">EdwardKerman式 <a class="header-anchor" href="#edwardkerman式" aria-label="Permalink to &quot;EdwardKerman式&quot;">​</a></h4><p><span class="mark-grey">#jnk：我觉得不会有其他形式了www</span></p><p><a href="http://www.bilibili.com/video/BV17tfVBmE8v" target="_blank" rel="noreferrer">b站视频链接</a></p><p>在Bresenham算法的基础上，令K=p/q, q=2^n，此时我们可以视n&#39;=q<em>n=pt，需要维护的偏差值a&#39;=q</em>a每单位时间增加p，当其超出q时，输出一个物品，每次输出一个物品相当于a&#39;减少q。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d695c7ebe8947225.q90-1147c35141249a34.webp" alt="物流原理与一些名词"></p><p>为了理解该结构，我们不妨给出一个简化版（不对轴）的p=(0011)_2，q=2^4的简单模型。a&#39;表现为分流器向右为0，向对向为1。两条带为进位，上面为1下面为0。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-1726a7669abd46bb.q90-db2d5200ccfdea4b.webp" alt="物流原理与一些名词"></p><p>对于每一位的加法，表示为 进位+p+a&#39;=a&#39;+进位 则</p><p>0+0+0=0表示物品在下方带，分流器在上方带，分流器向右，此时物品输出依旧在下方带，分流器不变<br> 0+1+0=1表示物品在下，分流器在下，分流器向右，此时物品依旧在下（无进位），分流器发生变化<br> 0+1+1=0+1表示物品下、分流器下、分流器向上，输出物品在上（有进位），分流器变化（0变1）</p><p>依次类推，会发现这种表示形式恰好满足了这所有八种可能的加法，因而输入一个物品能够表示a&#39;+p，且输出时如果进位为1，那么说明超出了q的范围，也就是a&#39;&gt;q了，对应输出了一个物品。</p><p>在连续输入多个物品时，为了保证不相互干扰计算，硬性要求物品从输入走任何一条路到任何一点的距离相同，这样这一点就不会同时接待两个物品，自然不相互干扰。</p><p><span id="source-block-rJLuoyW0sbNOPnKggEQMI8"></span></p><h3 id="简单有理分流器的均匀性" tabindex="-1">简单有理分流器的均匀性 <a class="header-anchor" href="#简单有理分流器的均匀性" aria-label="Permalink to &quot;简单有理分流器的均匀性&quot;">​</a></h3><p><span class="mark-grey">#jnk：这部分我不会，留给早色芋老大或者Cipolla_老大写吧www</span></p><p><span id="source-block-saFuJ384PvuWkO0x5E0uld"></span></p><h3 id="均匀有理限流器" tabindex="-1">均匀有理限流器 <a class="header-anchor" href="#均匀有理限流器" aria-label="Permalink to &quot;均匀有理限流器&quot;">​</a></h3><p><span id="source-block-Uj5kS4ulgYdVqCL6baJ4Ku"></span></p><h4 id="闰年算法" tabindex="-1">闰年算法 <a class="header-anchor" href="#闰年算法" aria-label="Permalink to &quot;闰年算法&quot;">​</a></h4><p><span id="source-block-xQRRd0h5FlKNP3iUeDlYjq"></span></p><h2 id="理想系统物流理论" tabindex="-1">理想系统物流理论 <a class="header-anchor" href="#理想系统物流理论" aria-label="Permalink to &quot;理想系统物流理论&quot;">​</a></h2><p>完整内容参见<a href="/endfield-skydoc/zh/flow-theory-for-idealized-logistics-systems">理想系统的流量理论</a>，以下文案均为入门内容，且在一定程度上缺乏校对。</p><p><span id="source-block-cHTDahDFpgGCpDwr4dbuTD"></span></p><h3 id="理想系统是什么-有什么用" tabindex="-1">理想系统是什么，有什么用 <a class="header-anchor" href="#理想系统是什么-有什么用" aria-label="Permalink to &quot;理想系统是什么，有什么用&quot;">​</a></h3><p>理想系统是一张有向图，每条边带一个容量。与终末地中物流器与传送带组成的网络（终末地物流系统）有一定对应关系。通过这些对应关系，我们可以将离散的物流系统一定程度转化为连续的理想系统模型进行<em><strong>研究</strong></em>，进一步的，可以<strong>计算</strong>结构通行流量大小、针对目标输入输出<strong>设计</strong>理想系统结构并转化为物流系统结构、<strong>证明</strong>稳态的存在与唯一等、<strong>解释</strong>结构形成特定流量的原因。</p><p><span id="source-block-gxkkNKNrBqUpClRYQfGYUv"></span></p><h4 id="一些定义" tabindex="-1">一些定义 <a class="header-anchor" href="#一些定义" aria-label="Permalink to &quot;一些定义&quot;">​</a></h4><p>理想系统中有四种点，输入（源仓库，对应输入流量到网络中）、输出（目标仓库，对应从网络输出流量）、分流节点（分流器，字面含义对应分流器）、汇流节点。</p><p>我们目前只关心稳态下的理想系统，下面的定义多是对稳态下节点与边的状态的定义，不一定适用于动态。</p><p>理想系统中的节点端口（与其连接的边对应）状态：<strong>轮询</strong>与<strong>非轮询</strong>。<span class="mark-grey">在理想系统++中还有高优先态，但是这里不做说明。</span><br> 轮询对应物理上，只要轮询到了就有物品/空位可以接受，例如分流器的两个端口都是轮询态，说明两个端口都在被轮询到时一定是空的可以输出。<br> 非轮询则是对应存在轮询到该端口但是无法输出的情况（存在而非总是），例如输入满带的二分分流器，两个端口中有一个端口接了1/5限速器，那么这个接口即使有1/2的情况被轮询到，但也无法输出，算式非轮询态</p><p>理想系统中的边状态：<strong>阻塞</strong>与<strong>流通</strong>，或者非流通、阻塞且流通、非阻塞。以及特殊状态的满带、空带。<span class="mark-grey">满带与空带就是物品满了和没有物品，不做过多解释。</span><br> 阻塞对应下游节点端口状态为轮询，其类似于边中物品总是不会减少太多，使得下游只要想取就有<br> 流通对应上游节点端口状态为轮询，其类似于边中物品总是不会增加太多，使得总是有空位接受上游输入<br> 非流通、非阻塞对应物品不断增加直到满带、物品不断减少直到空带，显而易见的对应两个非轮询，阻塞且流通对应物品不增不减的维持非满非空状态，对应上下游均轮询。上下游均非轮询为未定义情况，正常不会出现。</p><p><span id="source-block-CZFzmIr2D0AzZbwvw5p6Qa"></span></p><h3 id="三态模型规则介绍" tabindex="-1">三态模型规则介绍 <a class="header-anchor" href="#三态模型规则介绍" aria-label="Permalink to &quot;三态模型规则介绍&quot;">​</a></h3><p>三态模型是理想系统对边状态定义得到三种边状态的模型，在上述一大堆定义后，我们有多套等价的模型，三态模型的优点在于直观，可以明显的看到与实际物理的对应关系（看边上物品多不多）。</p><p><strong>基本要求</strong>：流量守恒、默认阻塞且流通对应流量为1、边不能非流通且非阻塞<br><strong>边缘状态</strong>：输入的出边阻塞、输出的入边流通**<br> 节点均分**：分流节点的下游流通边流量相等、汇流节点的上游阻塞边流量相等<br><strong>状态流量</strong>：分流节点的阻塞下游流量小于等于流通下游流量[0]、汇流节点的流通上游流量小于等于阻塞上游流量<br><strong>阻塞传播</strong>：分流节点存在流通出边，当且仅当入边流通[1]、分流节点入边阻塞，当且仅当所有出边阻塞、汇流节点存在阻塞入边，当且仅当出边阻塞、汇流节点出边流通，当且仅当所有入边流通；<span class="mark-grey">等价描述为节点存在流通出边&lt;=&gt;所有入边流通，节点存在阻塞入边&lt;=&gt;所有出边阻塞</span><br> 这里简单介绍一下[0][1]怎么来的，其他就自己理解吧<br> [0]还是那个满带输入二分流器，正常情况它应该两边各一半，但是其中限流一边没办法接受一半，不接受的物品会被分流器继续尝试轮询给下个输出，于是原本属于限流这边的物品就流向了非限流这边，自然限流这边的流量不如非限流方向流量<br> [1]分流节点存在流通出边，那么它可以将被阻塞的物品轮询给流通边，它内部不会有物品堵住就可以随时接受上游输入，进而使得上游也非阻塞</p><p>三态模型可以用于判断计算结果是否正确符合常理，进而使用MILP方法求解特定结构流量。</p></div>',1)])])}const u=e(o,[["render",t]]);export{b as __pageData,u as default};
